package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.web.context.request.RequestAttributes;
import org.springframework.web.context.request.RequestContextHolder;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The request attribute naming the steward whose delegation the request's user acts under;
     *  every record of the change it makes then ends with {@code for=} that steward. */
    public static final String FOR = Audit.class.getName() + ".for";

    /** Records that only report figures, which never carry {@code for=}. A SNAPSHOT is the
     *  record of the today change its user made, so it carries it. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused
     * or rolled back writes nothing. Outside a transaction the record is appended at once.
     */
    public void recordOnCommit(String record) {
        String entry = withFor(record);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** The record ending with {@code for=} the steward the request's user acts for, if it does,
     *  unless it only reports figures. */
    private static String withFor(String entry) {
        RequestAttributes request = RequestContextHolder.getRequestAttributes();
        Object steward = request == null ? null : request.getAttribute(FOR, RequestAttributes.SCOPE_REQUEST);
        if (steward == null || FIGURES.contains(entry.substring(0, Math.max(entry.indexOf(' '), 0)))) {
            return entry;
        }
        return entry + " for=" + steward;
    }

    /**
     * The sheet's records exactly as the file holds them, newest first; with a name (not blank),
     * only those about that person: carrying {@code name=} or {@code person=} that name, compared
     * as names are (case and surrounding spaces ignored).
     */
    public synchronized List<String> lines(String sheetId, String name) {
        List<String> all = read();
        String who = name == null ? "" : name.trim();
        List<String> found = new ArrayList<>();
        for (String line : all) {
            if (hasField(line, "sheet", sheetId, false)
                    && (who.isEmpty() || hasField(line, "name", who, true) || hasField(line, "person", who, true))) {
                found.add(line);
            }
        }
        Collections.reverse(found);
        return found;
    }

    /**
     * The sheet's records about one claim exactly as the file holds them, newest first: with a
     * number, those carrying {@code number=} it; without, those naming its person, amount and date
     * together ({@code person=.. amount=.. date=..}) that carry no number of their own.
     */
    public synchronized List<String> claimLines(String sheetId, String number, String person, String amount,
            String date) {
        String about = person + " amount=" + amount + " date=" + date;
        List<String> found = new ArrayList<>();
        for (String line : read()) {
            if (!hasField(line, "sheet", sheetId, false)) {
                continue;
            }
            boolean match = number != null
                    ? hasField(line, "number", number, false)
                    : !line.contains(" number=") && hasField(line, "person", about, false);
            if (match) {
                found.add(line);
            }
        }
        Collections.reverse(found);
        return found;
    }

    private List<String> read() {
        try {
            return Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Whether the record carries the field {@code key=value}: after the event name, ending the
     *  line or followed by a space. */
    private static boolean hasField(String line, String key, String value, boolean ignoreCase) {
        String field = " " + key + "=";
        for (int at = line.indexOf(field); at >= 0; at = line.indexOf(field, at + 1)) {
            int start = at + field.length();
            int end = start + value.length();
            if (end <= line.length() && line.regionMatches(ignoreCase, start, value, 0, value.length())
                    && (end == line.length() || line.charAt(end) == ' ')) {
                return true;
            }
        }
        return false;
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.session.CurrentUser;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** The audit viewer: reads what the audit file holds for a sheet; it is not a second record. */
@RestController
@RequestMapping("/api/sheets")
@Validated
public class AuditController {

    private final Audit audit;
    private final PersonRepository people;
    private final SheetService sheets;
    private final ClaimRepository claims;

    public AuditController(Audit audit, PersonRepository people, SheetService sheets, ClaimRepository claims) {
        this.audit = audit;
        this.people = people;
        this.sheets = sheets;
        this.claims = claims;
    }

    /** The sheet's audit lines, newest first; with a name, only those about that person, followed
     *  by those about them on each of the sheet's descendants (sheets by id, each newest first),
     *  then, when that person was transferred here, by the lines about them on the sheet they came from
     *  (newest first, as that sheet's file holds them). */
    @GetMapping("/{id}/audit")
    public List<String> lines(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @RequestParam(defaultValue = "") @Size(max = 200) String name) {
        List<String> lines = new ArrayList<>(audit.lines(id, name));
        String who = name.trim();
        if (!who.isEmpty()) {
            sheets.descendants(id).forEach(d -> lines.addAll(audit.lines(d, who)));
            people.findBySheetIdAndNameIgnoreCase(id, who).stream()
                    .map(Person::getOriginSheetId).filter(Objects::nonNull).findFirst()
                    .ifPresent(origin -> lines.addAll(audit.lines(origin, who)));
        }
        return lines;
    }

    /** The claim's timeline: the audit lines about it, newest first, as the file holds them — those
     *  carrying its number, or for a claim with no number those naming its person, amount and date
     *  together. Refused (404) when the claim is not on the sheet. */
    @GetMapping("/{id}/claims/{claimId}/timeline")
    public List<String> timeline(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String id,
            @PathVariable long claimId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        Claim claim = claims.findByIdAndSheetId(claimId, id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        Person person = people.findById(claim.getPersonId())
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        return audit.claimLines(id, claim.getNumber(), person.getName(),
                claim.getAmount().setScale(2).toPlainString(), claim.getDate().toString());
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

// The sheet's audit lines, read from the audit file through the server.
@Injectable({ providedIn: 'root' })
export class AuditApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's audit lines as the file holds them, newest first; with a name, only those about
   *  that person. */
  lines(sheetId: string, name: string): Promise<string[]> {
    return firstValueFrom(this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/audit`, {
      params: { name },
      headers: { 'X-User': this.session.user() ?? '' },
    }));
  }
}
import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session, otherError } from '../../core/session';
import { AuditApi } from './audit-api';

// The audit viewer: the sheet's audit lines as the file holds them, newest first; with a name in
// the filter, only the lines about that person (name= or person= it, case and spaces ignored),
// followed by those about them on each of the sheet's descendants (sheets by id, each newest
// first), then, for a person transferred here, by those about them on the sheet they came from.
@Component({
  selector: 'app-audit-viewer',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="audit-heading">
      <h2 id="audit-heading">Audit</h2>
      <form [formGroup]="filterForm" (ngSubmit)="show()" aria-label="Show audit lines">
        <label for="audit-filter">Person (blank: every line)</label>
        <input id="audit-filter" data-testid="audit-filter" formControlName="name" autocomplete="off" />
        <button type="submit" data-testid="audit-show">Show</button>
        @if (error(); as err) {
          <p role="alert" data-testid="audit-error">{{ err }}</p>
        }
      </form>
      <ol data-testid="audit-lines">
        @for (line of lines(); track $index) {
          <li data-testid="audit-line">{{ line }}</li>
        }
      </ol>
    </section>
  `,
})
export class AuditViewer {
  private readonly session = inject(Session);
  private readonly api = inject(AuditApi);

  protected readonly filterForm = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
  });
  protected readonly lines = signal<string[]>([]);
  protected readonly error = signal<string | null>(null);

  constructor() {
    this.filterForm.valueChanges.subscribe(() => this.error.set(null));
  }

  protected async show(): Promise<void> {
    this.error.set(null);
    this.lines.set([]);
    const id = this.session.sheetId();
    if (!id) {
      this.error.set('Load a sheet first.');
      return;
    }
    try {
      this.lines.set(await this.api.lines(id, this.filterForm.controls.name.value.trim()));
    } catch (e) {
      this.error.set(otherError(e));
    }
  }
}
